+                if ($previousCharacter === '@') {
+                    $nextCursor = $openingPosition + $openingLength;
+
+                    if ($nextCursor < $haystackLength) {
+                        $cursor = $nextCursor;
+
+                        continue;
+                    }
+
+                    break;
+                }
+            }
+
+            $contentStart = $openingPosition + $openingLength;
