+
+            if ($closingPosition === false) {
+                break;
+            }
+
+            $innerContent = substr($haystack, $contentStart, $closingPosition - $contentStart);
+            $matchEnd = $closingPosition + $closingLength;
+
+            $replacements->push([
+                'start' => $openingPosition,
+                'end' => $matchEnd,
+                'inner' => $innerContent,
+            ]);
+
+            $cursor = $matchEnd;
+        }
+
+        if ($replacements->isEmpty()) {
+            return $value;
+        }
+
+        $firstReplacement = $replacements->first();
+        $output = '';
+        $emitted = 0;
+
+        if ($firstReplacement['start'] > 0) {
+            $output = substr($haystack, 0, $firstReplacement['start']);
+            $emitted = $firstReplacement['start'];
+        }
+
+        foreach ($replacements->all() as $replacement) {
+            $start = $replacement['start'];
+            $end = $replacement['end'];
+            $innerContent = $replacement['inner'];
+
+            if ($start > $emitted) {
+                $output .= substr($haystack, $emitted, $start - $emitted);
+            }
+
+            $this->rawBlocks[] = $innerContent;
+            $blockIndex = count($this->rawBlocks) - 1;
+            $placeholderPattern = '@__raw_block_#__@';
+            $placeholder = str_replace('#', (string) $blockIndex, $placeholderPattern);
+            $output .= $placeholder;
+            $emitted = $end;
+        }
+
+        if ($emitted < $haystackLength) {
+            $output .= substr($haystack, $emitted);
